/* WikiAula — textos de gen/mat9.js (Matemáticas, Grado 9), en español. */
"use strict";
(function () {
const G = window.WA.I18N.es.gen;
const S = G.m9 = G.m9 || {};
const neg = n => n < 0 ? "−" + Math.abs(n) : String(n);
const PL = ["las décimas", "las centésimas"];
const P_ = s => String(s).startsWith("−") ? `(${s})` : String(s);   // negativos entre paréntesis
const BY = b => b === "1" ? "y" : b === "−1" ? "−y" : b + "y";   // 3y, −y, y
const TY = b => b.startsWith("−") ? " − " + BY(b.slice(1)) : " + " + BY(b);   // + 3y, − y
const WA_LIN = (p, q) => window.WA.MATH.lin(p, q, "n");   // 3n + 1, −2n, n − 4
// fracción final: «a/b = simplificada», o solo «a/b» si ya es irreducible (sin igualdades repetidas)
const fin = (raw, v) => String(v).replace(/<[^>]+>/g, "") === raw ? `<b>${raw}</b>` : `${raw} = <b>${v}</b>`;
Object.assign(S, {
  and: " y ",
  next: "Siguiente término",
  O: "O",
  set_hint: "Escribe las soluciones separadas por comas, por ejemplo: 2, −3",
  pol_hint: "Escribe los polinomios con x y ^, por ejemplo: 2x^2 − 3x + 1",

  er_q: (x, k) => `Redondea <b>${x}</b> a ${PL[k - 1]} y calcula el error absoluto que se comete.`,
  er_f: ["Aproximación", "Error absoluto"],
  er_s: (x, a, e) => `Al redondear, ${x} ≈ <b>${a}</b>. Error absoluto = |valor real − aproximación| = |${x} − ${a}| = <b>${e}</b>.`,
  err_q: (r, m) => `Una pieza mide en realidad ${r} mm, pero una medición da ${m} mm. ¿Cuál es el error relativo, en porcentaje? (Dos decimales.)`,
  err_s: (r, m, e, p, q, ex) => `Error absoluto: |${r} − ${m}| = ${e} mm. Error relativo: ${e}/${r} ${ex ? "=" : "≈"} ${q}; en porcentaje, ${q} · 100 = <b>${p} %</b>.`,
  ct_q: (x, k, u) => `Una medida se ha redondeado a ${PL[k - 1]}: <b>${x} ${u}</b>. ¿Cuál es la cota del error absoluto? ¿Y la cota del error relativo, en porcentaje? (Una cifra decimal.)`,
  ct_u: ["m", "kg", "L", "s", "cm"],
  ct_f: ["Cota del error absoluto", "Cota del error relativo (%)"],
  ct_s: (k, c, x, q, p, u) => `Al redondear a ${PL[k - 1]}, el error es como mucho media ${["décima", "centésima"][k - 1]}: <b>${c} ${u}</b>. Cota del error relativo: ${c}/${x} ≈ ${q}; en porcentaje, ${q} · 100 ≈ <b>${p} %</b>.`,
  tr0_q: (x, k) => `Aproxima <b>${x}</b> a ${PL[k - 1]} truncando y redondeando.`,
  tr0_f: ["Truncamiento", "Redondeo"],
  tr0_s: (x, k, t, dig, up, r) => `Truncar: se cortan las cifras que sobran: <b>${t}</b> (por defecto, porque es menor que ${x}). Redondear: la primera cifra que se suprime es un ${dig}, ${dig >= 5 ? `5 o mayor, así que se sube una unidad la última: <b>${r}</b>, que es mayor que ${x}: por exceso` : `menor que 5, así que se deja igual: <b>${r}</b>, por defecto, como el truncamiento`}.`,
  cs_q: s => `¿Cuántas cifras significativas tiene <b>${s}</b>?`,
  cs_s: (s, z, list, n, mid) => `${z ? `En ${s}, ${z === 1 ? "el 0 inicial no cuenta: solo sirve" : `los ${z} ceros iniciales no cuentan: solo sirven`} para colocar la coma. ` : ""}Cuentan todas ${z ? "las demás cifras" : "sus cifras"}${mid ? ", también los ceros que hay entre ellas o al final de la parte decimal" : ""}: ${list}. Son <b>${n}</b> cifras significativas.`,

  dt_q: f => `Sin hacer la división, ¿qué tipo de decimal da la fracción <b>${f}</b>?`,
  dt_o: ["Decimal exacto", "Periódico puro", "Periódico mixto"],
  dt_s: (f, fi, k, fac, c) => `${fi ? `Primero se simplifica: ${f} = ${fi} (dividiendo entre ${k}). ` : `${f} ya es irreducible. `}Su denominador es ${fac}: ${["no tiene más factores primos que el 2 y el 5, así que da un <b>decimal exacto</b>", "no tiene ni 2 ni 5, así que da un <b>periódico puro</b>", "tiene un 2 o un 5 y además otros primos, así que da un <b>periódico mixto</b>"][c]}.${fi ? " Si miras el denominador sin simplificar, te equivocas." : ""}`,
  dg_q: x => `Calcula la fracción generatriz de <b>${x}</b> y simplifícala.`,
  dg_s: (x, m1, bigS, m0, smallS, den, num, big, small, k, a, f0, r) => {
    const resta = m0 === 1
      ? `El periodo tiene ${k === 1 ? "una cifra" : "dos cifras"}: multiplicamos por ${m1}, ${m1}x = ${bigS}, y restamos x: ${m1}x − x = ${bigS} − ${x} = ${num}, es decir, ${den}x = ${num}.`
      : `Multiplicamos por ${m1} (la coma, tras el primer periodo) y por ${m0} (la coma, justo antes del periodo): ${m1}x = ${bigS} y ${m0}x = ${smallS}, con la misma cola. Restamos: ${m1}x − ${m0}x = ${bigS} − ${smallS} = ${num}, es decir, ${den}x = ${num}.`;
    const regla = `${k === 1 ? "un nueve" : "dos nueves"}${a ? (a === 1 ? " y un cero" : " y dos ceros") : ""}`;
    return `Con la resta: llamamos x = ${x} ${resta} Con la regla: numerador ${big} − ${small} = ${num}; denominador, ${regla}: ${den}. En los dos casos, x = ${f0 === r ? `<b>${r}</b>, que ya es irreducible` : `${f0} = <b>${r}</b>`}.`;
  },
  ir_q: x => `¿El número <b>${x}</b> es racional o irracional?`,
  ir_o: ["Racional", "Irracional"],
  ir_r: {
    cuad: (n, r) => `√${n} = ${r}, un número entero: es <b>racional</b>.`,
    nocuad: n => `${n} no es un cuadrado perfecto, así que √${n} no es exacta: tiene infinitas cifras sin periodo. Es <b>irracional</b>.`,
    pi: "π = 3,14159… tiene infinitas cifras decimales sin periodo: es <b>irracional</b>.",
    frac: "Es una fracción de dos enteros: es <b>racional</b>.",
    per: "Es un decimal periódico (0,333… = 1/3): es <b>racional</b>.",
    sinper: "Tiene infinitas cifras y ningún bloque se repite siempre igual (cada vez hay un cero más): es <b>irracional</b>.",
    cfrac: (n, d, a, b, a1, b1) => `√(${n}/${d}) = ${a}/${b}${a1 === a ? "" : ` = ${a1}/${b1}`}, una fracción: es <b>racional</b>.`,
    suma: (k, t) => `√${t} es irracional, y un racional más un irracional nunca es racional: ${k} + √${t} es <b>irracional</b>.`,
    exacto: "Es un decimal exacto: es <b>racional</b>.",
    e: "e = 2,718281… tiene infinitas cifras decimales sin periodo: es <b>irracional</b>.",
    kpi: k => `π es irracional y, al multiplicarlo por un racional distinto de 0, sigue siéndolo: ${k}π es <b>irracional</b>.`,
    cubo: (n, r) => `∛${n} = ${r}, porque ${r}³ = ${n}: es <b>racional</b>.`,
    nocubo: n => `${n} no es un cubo perfecto, así que ∛${n} no es exacta: es <b>irracional</b>.`,
    prod: (a, b, p, r) => `¡Cuidado! √${a} · √${b} = √${p} = ${r}: el producto de dos irracionales puede ser racional. Es <b>racional</b>.`,
  },

  pf_q: e => `Calcula <b>${e}</b>.`,
  pf_s: (a, m, n, b, r) => `a<sup>m/n</sup> = (<sup>n</sup>√a)<sup>m</sup>: la raíz ${n === 2 ? "cuadrada" : "cúbica"} de ${a} es ${m === 1 ? `<b>${b}</b>` : `${b}, y ${b}<sup>${m}</sup> = <b>${r}</b>`}.`,
  pf2_q: r => `¿Qué potencia equivale al radical <b>${r}</b>?`,
  pf2_s: ok => `El índice de la raíz pasa al denominador del exponente: <sup>n</sup>√a<sup>m</sup> = a<sup>m/n</sup>. Simplificando: <b>${ok}</b>.`,
  po_q: e => `Escribe como un solo radical: <b>${e}</b>`,
  po_s: (pw, base, s, s2, raw, f, ok) => `Como potencias: ${pw} = ${base}<sup>${s}</sup>. Común denominador: ${s2} = ${raw ? `${raw} = ` : ""}${f}. Volvemos a radical: ${base}<sup>${f}</sup> = <b>${ok}</b>.`,
  pn_s: (a, m, n, b, r) => `Primero la raíz: la raíz ${n === 2 ? "cuadrada" : "cúbica"} de ${a} es ${b}${m > 1 ? `; después la potencia, ${b}<sup>${m}</sup> = ${r}` : ""}. El exponente negativo invierte: <b>1/${r}</b>.`,
  ps_q: e => `Calcula <b>${e}</b> (el resultado es un número entero).`,
  ps_s: (div, p, r, q, k, base, v) => `Misma base: ${div ? "se restan" : "se suman"} los exponentes. ${p}/${q} ${div ? "−" : "+"} ${r}/${q} = ${div ? p - r : p + r}/${q} = ${k}, así que queda ${base}<sup>${k}</sup> = <b>${v}</b>.`,
  re0_q: (n, a) => `¿Cuántas soluciones reales tiene la ecuación <b>x<sup>${n}</sup> = ${a}</b>?`,
  re0_o: ["Ninguna", "Una", "Dos"],
  re0_s: [
    (n, a) => `Índice par y número negativo: ninguna potencia de exponente par es negativa, así que <b>no hay solución real</b>.`,
    (n, a, b) => `Índice impar: hay <b>una</b> solución, con el signo del número: x = ${a.startsWith("−") ? "−" + b : b}, porque ${a.startsWith("−") ? "(−" + b + ")" : b}<sup>${n}</sup> = ${a}.`,
    (n, a, b) => `Índice par y número positivo: <b>dos</b> soluciones opuestas, x = ${b} y x = −${b}, porque ${b}<sup>${n}</sup> = ${a} y (−${b})<sup>${n}</sup> = ${a}.`,
  ],
  re1_q: r => `Simplifica el radical <b>${r}</b> y escríbelo con el índice más pequeño posible. ¿Qué índice y qué exponente quedan dentro?`,
  re1_f: ["Índice", "Exponente"],
  re1_s: (r, k, r2, n, m) => `Se dividen el índice y el exponente entre el mismo número, ${k}: ${r} = <b>${r2}</b>. Índice <b>${n}</b> y exponente <b>${m}</b>.`,
  re2_q: (a, b) => `¿Qué número es mayor, <b>${a}</b> o <b>${b}</b>?`,
  re2_o: (a, b) => [`${a} es mayor`, `${b} es mayor`, "Son iguales"],
  re2_s: (L, p, q, r1, r2, s1, s2, t1, t2, A, B, c) => `Se pasan al mismo índice, ${L} (el m.c.m. de ${p} y ${q}): ${[...new Set([r1, s1, t1])].join(" = ")}${p === L ? " (ya tiene ese índice)" : ""} y ${[...new Set([r2, s2, t2])].join(" = ")}${q === L ? " (ya tiene ese índice)" : ""}. ${c === 2 ? `Como ${A} = ${B}, <b>son iguales</b>.` : `Como ${Math.max(A, B)} &gt; ${Math.min(A, B)}, es mayor <b>${c === 0 ? r1 : r2}</b>.`}`,
  sc_q: e => `Calcula y escribe el resultado en notación científica (a · 10<sup>n</sup>, con 1 ≤ a &lt; 10): <b>${e}</b>`,
  sc_f: ["Mantisa a", "Exponente n"],
  sc_sum: (t2, t2b, m1, resta, m2b, p, s, fix) => `Para sumar o restar, las dos potencias deben ser iguales: pasamos a ${p}: ${t2} = ${t2b}. ${resta ? "Restamos" : "Sumamos"} las mantisas: (${m1} ${resta ? "−" : "+"} ${m2b}) · ${p} = ${fix ? `${s} · ${p}. Ajustamos la mantisa: <b>${fix}</b>` : `<b>${s} · ${p}</b>`}.`,
  sc_pow: (m, k, mk, e, ek, fix, raw) => `Se eleva la mantisa y se multiplica el exponente: ${m}<sup>${k}</sup> = ${mk} y 10<sup>${e} · ${k}</sup> = 10<sup>${ek}</sup>. ${fix ? `Queda ${raw}; ajustamos la mantisa: <b>${fix}</b>` : `Resultado: <b>${raw}</b>`}.`,
  sc_root: (odd, x, r2, e2, e0, r, f) => `${odd ? `El exponente ${neg(e0)} es impar: antes se reescribe, ${x} = ${r2} · 10<sup>${e2}</sup>. ` : ""}La raíz de la mantisa, √${r2} = ${r}, y la de la potencia, √10<sup>${e2}</sup> = 10<sup>${f}</sup> (se divide el exponente entre 2). Resultado: <b>${r} · 10<sup>${f}</sup></b>.`,
  ra_q: r => `Calcula <b>${r}</b>.`,
  ra_s: (b, n, x) => `Porque ${b.startsWith("−") ? "(" + b + ")" : b}<sup>${n}</sup> = ${x}, la raíz es <b>${b}</b>.`,
  rm_q: e => `Calcula <b>${e}</b> (el resultado es un número entero).`,
  rm_s: (a, b, p, m, n, r) => {
    const f = [`${p}²`, ...[m, n].filter(k => k > 1).map(k => `${k}²`)];
    const ds = [...new Set([[a, m], [b, n]].filter(([, k]) => k > 1).map(([x, k]) => `${x} = ${p} · ${k}²`))].join(" y ");
    return `√a · √b = √(a · b). No hace falta multiplicar: ${ds}, así que √(${a} · ${b}) = √(${f.join(" · ")}) = ${f.map(x => x.slice(0, -1)).join(" · ")} = <b>${r}</b>.`;
  },
  rd_s: (a, b, p, r) => `√a : √b = √(a : b): √(${a} : ${b}) = √${p} = <b>${r}</b>.`,
  ri_q: e => `Introduce el factor dentro de la raíz: <b>${e}</b> = √x. ¿Cuánto vale x?`,
  rx_q: (e, cube) => `Extrae factores del radical y escríbelo como a${cube ? "<sup>3</sup>" : ""}√b, con b lo más pequeño posible: <b>${e}</b>`,
  rx_f: ["a (fuera)", "b (dentro)"],
  rx_s: (r, n, fs, grp, cube, out, a, ins, b) => `Descomponemos ${n} = ${fs}${grp ? " = " + grp : ""}. Por cada grupo de ${cube ? "tres" : "dos"} factores iguales sale uno fuera de la raíz: fuera queda ${out}${out === String(a) ? "" : " = " + a} y dentro, ${ins}${ins === String(b) ? "" : " = " + b}. Así, ${r}${n} = <b>${a}${r}${b}</b>.`,
  rs_q: e => `Calcula y expresa el resultado como un múltiplo de un radical: <b>${e}</b>`,
  rs_f: b => `Coeficiente de √${b}`,
  rs_s: (ext, sub, sum, k, res) => `Extraemos factores: ${ext}. Sustituimos: ${sub}. Son semejantes, así que se suman los coeficientes: ${sum} = ${k}. Resultado: <b>${res}</b>.`,
  ri_s: (a, b, r) => `Para meter un factor en la raíz, se eleva al cuadrado: ${a}√${b} = √(${a}² · ${b}) = √<b>${r}</b>.`,

  st_q: (f, n) => `El término general de una sucesión es a<sub>n</sub> = ${f}. Calcula a<sub>${n}</sub>.`,
  st_s: (e, r) => `Sustituimos n: ${e} = <b>${r}</b>.`,
  tg_q: s => `¿Cuál es el término general de la sucesión ${s}, …?`,
  tg_s: (d, a, c, ok) => `Cada término es ${Math.abs(d)} ${d > 0 ? "más" : "menos"} que el anterior: la fórmula empieza por ${WA_LIN(d, 0)}. Para n = 1, ${WA_LIN(d, 0)} da ${neg(d)} y queremos ${neg(a)}: ${c === 0 ? "no hay que sumar nada" : c > 0 ? `hay que sumar ${c}` : `hay que restar ${-c}`}. Así, a<sub>n</sub> = <b>${ok}</b>.`,
  lu_q: (v, f) => `¿Qué lugar ocupa el número <b>${v}</b> en la sucesión a<sub>n</sub> = ${f}? (Si no pertenece a la sucesión, escribe 0.)`,
  lu_s: (p, q, v, inS, n0) => `Igualamos el término general a ${v}: ${WA_LIN(p, q)} = ${v}${q ? ` → ${p}n = ${v - q}` : ""} → n = ${v - q}/${p}${inS ? ` = ${n0}: es el término a<sub>${n0}</sub>. Ocupa el lugar <b>${n0}</b>.` : `, que no es un número natural: ${v} <b>no pertenece</b> a la sucesión (respuesta: 0).`}`,
  sn_q: s => `¿Cuál es el siguiente término de la sucesión ${s}, …?`,
  sn_s: (d, r) => `Cada término se obtiene ${d < 0 ? "restando " + Math.abs(d) : "sumando " + d} al anterior: el siguiente es <b>${r}</b>.`,
  pa_q: (a1, d, n) => `En una progresión aritmética, a<sub>1</sub> = ${a1} y la diferencia es d = ${d}. Calcula a<sub>${n}</sub>.`,
  pa_s: (n, a1, n1, d, r) => `a<sub>n</sub> = a<sub>1</sub> + (n − 1) · d → a<sub>${n}</sub> = ${a1} + ${n1} · ${d.startsWith("−") ? "(" + d + ")" : d} = <b>${r}</b>.`,
  pa2_q: (i, ai, j, aj) => `En una progresión aritmética, a<sub>${i}</sub> = ${ai} y a<sub>${j}</sub> = ${aj}. Calcula la diferencia d y el primer término a<sub>1</sub>.`,
  pa2_s: (aj, ai, k, d, a1, i, id) => `Entre los dos términos hay ${k} saltos: d = (${aj} − ${ai.startsWith("−") ? "(" + ai + ")" : ai}) / ${k} = <b>${d}</b>. Retrocediendo hasta el primero: de a<sub>${i}</sub> a a<sub>1</sub> hay ${i - 1} ${i === 2 ? "salto" : "saltos"}, así que a<sub>1</sub> = ${ai} − ${i - 1} · ${d.startsWith("−") ? "(" + d + ")" : d} = ${ai} ${id < 0 ? "+" : "−"} ${Math.abs(id)} = <b>${a1}</b>.`,
  pg_q: (a1, r, n) => `En una progresión geométrica, a<sub>1</sub> = ${a1} y la razón es r = ${r}. Calcula a<sub>${n}</sub>.`,
  pg_s: (n, a1, r, e, v) => `a<sub>n</sub> = a<sub>1</sub> · r<sup>n−1</sup> → a<sub>${n}</sub> = ${a1} · (${r})<sup>${e}</sup> = <b>${v}</b>.`,
  pg2_q: s => `La sucesión ${s}, … es una progresión geométrica. Calcula la razón y el siguiente término.`,
  pg2_s: (b, a, r, n) => `r = ${b} : ${a.startsWith("−") ? "(" + a + ")" : a} = <b>${r}</b>. El siguiente término es <b>${n}</b>.`,
  sa_q: (a1, d, n) => `Calcula la suma de los ${n} primeros términos de la progresión aritmética con a<sub>1</sub> = ${a1} y d = ${d}.`,
  sa_s: (n, an, a1, s, n1, d) => { const P = x => x.startsWith("−") ? "(" + x + ")" : x; return `Primero, el último término: a<sub>${n}</sub> = a<sub>1</sub> + (${n} − 1) · d = ${a1} + ${n1} · ${P(d)} = ${an}. Después, S<sub>${n}</sub> = (a<sub>1</sub> + a<sub>${n}</sub>) · ${n} / 2 = (${a1} + ${P(an)}) · ${n} / 2 = <b>${s}</b>.`; },
  pg3_q: (i, ai, j, aj) => `En una progresión geométrica, a<sub>${i}</sub> = ${ai} y a<sub>${j}</sub> = ${aj}. Calcula la razón r.`,
  pg3_s: (aj, ai, r3, r) => `De a uno a otro hay 3 saltos, así que se ha multiplicado tres veces por r: r³ = ${aj} : ${ai.startsWith("−") ? "(" + ai + ")" : ai} = ${r3}, y r = ∛${r3.startsWith("−") ? "(" + r3 + ")" : r3} = <b>${r}</b>.`,
  pp_q: [
    (V, p, n) => `Se invierten ${V} € al ${p} % de interés compuesto anual. ¿Cuánto dinero habrá al cabo de ${n} años? (Con calculadora; redondea a los céntimos.)`,
    (V, p, n) => `Un móvil de ${V} € pierde cada año el ${p} % de su valor. ¿Cuánto valdrá al cabo de ${n} años? (Con calculadora; redondea a los céntimos.)`,
  ],
  pp_s: (up, p, f, V, n, fn, res) => `${up ? "Ganar" : "Perder"} un ${p} % cada año es multiplicar por ${f}: es una progresión geométrica de razón ${f}. Al cabo de ${n} años: ${V} · ${f}<sup>${n}</sup> = ${V} · ${fn} ≈ <b>${res} €</b>.`,
  sp3_q: [
    (a, d, n) => `Marta ahorra ${a} € la primera semana y cada semana ${d} € más que la anterior. ¿Cuánto habrá ahorrado en total en ${n} semanas?`,
    (a, d, n) => `Un teatro tiene ${a} butacas en la primera fila y cada fila tiene ${d} más que la anterior. Si hay ${n} filas, ¿cuántas butacas tiene en total?`,
  ],
  sp3_i: [
    (a, d) => `Es una progresión aritmética con a<sub>1</sub> = ${a} y d = ${d}: hay que sumar sus términos.`,
    (a, d) => `Es una progresión aritmética con a<sub>1</sub> = ${a} y d = ${d}: hay que sumar sus términos.`,
  ],
  si2_q: t => `Calcula la suma infinita <b>${t} + …</b> (es una progresión geométrica).`,
  si2_s: (t1, t0, m, a1, omr, s) => `La razón es r = ${t1} : ${t0} = 1/${m}; como |r| &lt; 1, la suma infinita existe: S = a<sub>1</sub> / (1 − r) = ${a1} / (1 − 1/${m}) = ${a1} : ${omr} = <b>${s}</b>.`,
  sg_q: (a1, r, n) => `Calcula la suma de los ${n} primeros términos de la progresión geométrica con a<sub>1</sub> = ${a1} y r = ${r}.`,
  sg_s: (a1, r, n, s) => `S<sub>n</sub> = a<sub>1</sub> · (r<sup>n</sup> − 1) / (r − 1) = ${a1} · (${r}<sup>${n}</sup> − 1) / ${r - 1} = <b>${s}</b>.`,

  dv_q: (p, d) => `Divide <b>${p}</b> entre <b>${d}</b>. Escribe el cociente y el resto.`,
  dv_f: ["Cociente", "Resto"],
  dv_s: (p, d, q, r, steps) => `${steps} Cociente: <b>${q}</b>; resto: <b>${r}</b>. Comprobación: (${d}) · (${q})${r === "0" ? "" : / /.test(r) ? ` + (${r})` : r.startsWith("−") ? ` − ${r.slice(1)}` : ` + ${r}`} = ${p}.`,
  dv_step: (lead, dl, m, d, prod, next) => `${lead} : ${dl} = ${m}. Multiplicamos: ${m} · (${d}) = ${prod}. Restamos: queda ${next}.`,
  ru_q: (p, d) => `Divide por la regla de Ruffini <b>${p}</b> entre <b>${d}</b>.`,
  ru_s: (a, cs, q, r, first, cols) => `Coeficientes: ${cs}; a la izquierda, ${a}. Bajamos el ${first}. ${cols}. La fila de abajo da el cociente, <b>${q}</b>, y el último número es el resto, <b>${r}</b>.`,
  re_q: (p, d) => `Sin hacer la división, calcula el resto de dividir <b>${p}</b> entre <b>${d}</b>.`,
  re_s: (a, p, r, s, v) => `Por el teorema del resto, el resto es P(${a}). Sustituimos x = ${a} (con paréntesis): P(${a}) = ${s} = ${v} = <b>${r}</b>.`,
  rk_q: (p, d) => `¿Cuánto debe valer k para que <b>${p}</b> sea divisible entre <b>${d}</b>?`,
  rk_s: (a, k, s, v, mk) => `Es divisible si el resto P(${a}) es 0. P(${a}) = ${s} + k = ${v} + k = ${mk} + k. Para que sea 0: k = <b>${k}</b>.`,
  f2_q: p => `Factoriza el polinomio <b>${p}</b>.`,
  f2_s: (p, cs, q, ok, steps) => `Primero se saca el coeficiente principal: ${p} = ${cs}(${q}). Ahora se factoriza ${q}. ${steps} Resultado, con el coeficiente principal delante: <b>${ok}</b>.`,
  f3_q: p => `¿Cuántas raíces reales tiene el polinomio <b>${p}</b>?`,
  f3_s: (a, p, row, q, f1, k) => `Probamos los divisores del término independiente: x = ${a} da 0, ¡es raíz! Ruffini con a = ${a}: ${row}. Queda ${p} = (${f1})(${q}). El factor ${q} no tiene raíces reales (x² = −${k} es imposible): es <b>irreducible</b> y no se puede factorizar más. Hay <b>una</b> sola raíz real, x = ${a}.`,
  fa_q: (p, comun) => `Halla las raíces enteras del polinomio <b>${p}</b> (${comun ? "saca primero factor común" : "prueba con los divisores del término independiente"}).`,
  fa_s: (p, f, steps, rs) => `${steps} Resultado: ${p} = <b>${f}</b>. Las raíces son los valores que anulan cada factor: <b>${rs}</b>.`,
  fa_doble: " (doble)",
  fa_comun: (z, q) => `El término independiente es 0: sacamos factor común ${z === 1 ? "x" : "x²"}, y queda ${z === 1 ? "x" : "x²"}(${q}).`,
  fa_ruf: (c, dv, r, row, f1, q) => `Divisores de ${c}: ${dv}. Probamos x = ${r}: da 0, ¡es raíz! Ruffini con a = ${r}: ${row}. Queda (${f1})(${q}).`,
  fa_quad: (q, s, p, u, v) => `Para ${q}: dos números que sumen ${neg(s)} y multipliquen ${neg(p)}: ${u} y ${v}.`,

  bq_q: e => `Resuelve: <b>${e} = 0</b>`,
  bq_fac: (q, b, c, u, v, sols) => `Sacamos factor común x: x(${q}) = 0. Un producto vale 0 si algún factor vale 0: x = 0, o bien ${q} = 0, que da x = ${u} y x = ${v}. Soluciones: <b>${sols}</b>.`,
  bq_zc: (eq, s) => `${eq} = 0 → z(z − ${s}) = 0: z = 0 o z = ${s}`,
  bq_zf: (eq, s, D, r, z1, z2) => `${eq} = 0 → z = (${s} ± √${D}) / 2 = (${s} ± ${r}) / 2: z = ${z1} o z = ${z2}`,
  bq_s: (eq, how, z1, z2, a, sols) => {
    const back = z => z < 0 ? `z = ${neg(z)} no da soluciones (x² no puede ser negativo)` : z === 0 ? "z = 0 da x = 0" : `z = ${z} da x = ±${Math.sqrt(z)}`;
    return `Cambio z = x² (y x⁴ = z²): ${how}. Deshacemos el cambio: ${back(z1)}; ${back(z2)}. Soluciones: <b>${sols}</b>.`;
  },
  di_q: p => `Sin resolverla, ¿cuántas soluciones tiene la ecuación <b>${p} = 0</b>?`,
  di_o: ["Dos soluciones", "Una solución (doble)", "Ninguna solución real"],
  di_s: (b, a, c, D, n) => `Δ = b² − 4ac = ${b.startsWith("−") ? "(" + b + ")" : b}² − 4 · ${a < 0 ? "(" + neg(a) + ")" : a} · ${c.startsWith("−") ? "(" + c + ")" : c} = ${neg(D)}. ${["Como Δ &gt; 0, hay <b>dos soluciones</b>.", "Como Δ = 0, hay <b>una solución doble</b>.", "Como Δ &lt; 0, <b>no hay solución real</b>."][n]}`,
  sg2_q: e => `Resuelve la ecuación <b>${e}</b>.`,
  sg2_o: std => `Quitamos el paréntesis y pasamos todo a un lado: <b>${std} = 0</b>.`,
  sg2_p: (sq, rhs, std) => `Desarrollamos el cuadrado: ${sq} = ${rhs}. Pasamos todo a un lado y agrupamos: <b>${std} = 0</b>.`,
  sg2_d: (m6, ex, big, std) => `Multiplicamos los dos lados por 6 (el m.c.m. de 2 y 3): ${m6}, es decir, ${ex}. Pasamos todo a un lado: ${big} = 0, y dividimos entre 3: <b>${std} = 0</b>.`,
  sg2_k: (k, std) => k === "−1" ? `El coeficiente de x² es negativo: multiplicamos todo por −1 (cambian todos los signos) y queda <b>${std} = 0</b>.` : `Todos los coeficientes son múltiplos de ${k}: dividimos entre ${k} y queda <b>${std} = 0</b>, con números más pequeños.`,
  sg2_f: (s, s2, m4p, D, r, sols) => `Fórmula con a = 1: x = (${s} ± √(${s2} ${m4p < 0 ? "−" : "+"} ${Math.abs(m4p)})) / 2 = (${s} ± √${D}) / 2 = (${s} ± ${r}) / 2: x = <b>${sols[0]}</b> o x = <b>${sols[1]}</b>.`,
  er2_q: e => `Resuelve la ecuación <b>${e}</b>.`,
  er2_s: (k, sx, std) => `Valor prohibido: x = 0 (anula el denominador). Multiplicamos todo por x: x² ${k.startsWith("−") ? "− " + k.slice(1) : "+ " + k} = ${sx}, es decir, ${std} = 0.`,
  er2_ok: "Ninguna es 0, el valor prohibido: las dos valen.",
  er3_q: e => `Resuelve la ecuación <b>${e}</b>.`,
  er3_no: "No tiene solución",
  er3_s: (a, d, b, c, b1, ab1) => `Valor prohibido: x = ${a} (anula el denominador). Multiplicamos todo por (${d}): x + ${b === 1 ? "" : b}(${d}) = ${a}, es decir, ${b1}x ${c < 0 ? "−" : "+"} ${Math.abs(c)} = ${a}, y ${b1}x = ${ab1}: x = ${a}. ¡Pero x = ${a} es el valor prohibido! Es una solución falsa: la ecuación <b>no tiene solución</b>.`,
  er4_q: e => `Resuelve la ecuación <b>${e}</b>.`,
  er4_s: (a, b, m, d2, n, d1, l, r, mn, rhs, x) => `Valores prohibidos: x = ${a} y x = ${b}. Multiplicamos los dos lados por (${d1})(${d2}): ${m === "1" ? "" : m === "−1" ? "−" : m}(${d2}) = ${n === "1" ? "" : n === "−1" ? "−" : n}(${d1}), es decir, ${l} = ${r}. Agrupamos: ${mn} = ${rhs}, así que x = <b>${x}</b>, que no es ningún valor prohibido: vale.`,
  ep3_q: (c, d) => `En un triángulo rectángulo de hipotenusa ${c} cm, un cateto mide ${d} cm más que el otro. ¿Cuánto mide el cateto menor?`,
  ep3_s: (c, d, k2, K, D, r, a, b, e2, e1) => `Si el cateto menor mide x, el otro mide x + ${d}. Pitágoras: x² + (x + ${d})² = ${c}², es decir, ${e2} = 0; dividiendo entre 2, ${e1} = 0. Fórmula: x = (−${d} ± √${D}) / 2 = (−${d} ± ${r}) / 2: x = <b>${a}</b> (la otra solución es negativa y no vale para una longitud). Los catetos miden ${a} y ${b} cm.`,
  ep4_q: (v, H) => `Se lanza una pelota hacia arriba y su altura es h = ${v}t − 5t² (h en metros, t en segundos). ¿En qué instantes está a ${H} m de altura?`,
  ep4_s: (v, H, s, p, t1, t2) => `${v}t − 5t² = ${H} → 5t² − ${v}t + ${H} = 0 → dividiendo entre 5: t² − ${s}t + ${p} = 0. Fórmula: t = (${s} ± √(${s * s} − ${4 * p})) / 2 = (${s} ± ${t2 - t1}) / 2: t = <b>${t1}</b> s (al subir) y t = <b>${t2}</b> s (al bajar). Las dos valen.`,
  ep_q: [
    p => `El producto de dos números naturales consecutivos es ${p}. ¿Cuál es el menor?`,
    (P, A) => `Un rectángulo tiene ${P} m de perímetro y ${A} m² de área. ¿Cuánto miden sus lados?`,
    (d, A) => `Si al lado de un cuadrado se le suman ${d} cm, el área del nuevo cuadrado es ${A} cm². ¿Cuánto mide el lado del cuadrado original?`,
  ],
  ep_s: [
    (p, x, y) => `Si el menor es x, el siguiente es x + 1: x(x + 1) = ${p}, es decir, x² + x − ${p} = 0. Fórmula: x = (−1 ± √(1 + ${4 * p})) / 2 = (−1 ± √${1 + 4 * p}) / 2 = (−1 ± ${2 * x + 1}) / 2 (la raíz, con calculadora). x = <b>${x}</b>; la otra, −${y}, no es natural. Comprobación: ${x} · ${y} = ${p} ✓.`,
    (s, p, a, b) => `Largo y ancho suman la mitad del perímetro, ${s} m. Si un lado mide x, el otro mide ${s} − x. Área: x(${s} − x) = ${p}, es decir, x² − ${s}x + ${p} = 0. Fórmula: x = (${s} ± √(${s * s} − ${4 * p})) / 2 = (${s} ± √${(b - a) ** 2}) / 2 = (${s} ± ${b - a}) / 2: x = ${b} o x = ${a}. Los lados miden <b>${a}</b> m y <b>${b}</b> m.`,
    (d, A, l, x) => `El lado nuevo mide x + ${d}: (x + ${d})² = ${A} → x + ${d} = √${A} = ${l} (la solución negativa, −${l}, no vale para una longitud) → x = <b>${x}</b> cm.`,
  ],

  ti_q: (e1, e2) => `¿De qué tipo es el sistema <b>${e1}</b>; <b>${e2}</b>?`,
  ti_o: ["Compatible determinado (una solución)", "Compatible indeterminado (infinitas)", "Incompatible (ninguna)"],
  ti_s: [
    (m, ra, rb) => `Comparamos los coeficientes: para pasar de la x de la primera a la de la segunda hay que multiplicar por ${ra}, y para la y, por ${rb}. No es el mismo número: los coeficientes no son proporcionales y las rectas se cortan en un punto. Es <b>compatible determinado</b>.`,
    (m, ra, rb, a, b, c, a2, b2, c2) => `La segunda ecuación es la primera multiplicada por ${neg(m)}: ${a} · ${P_(neg(m))} = ${a2}, ${b} · ${P_(neg(m))} = ${b2} y ${c} · ${P_(neg(m))} = ${c2}. Son la misma recta. Es <b>compatible indeterminado</b>.`,
    (m, ra, rb, a, b, c, a2, b2, c2, mc) => `Los coeficientes de x y de y se multiplican por ${neg(m)} (${a} · ${P_(neg(m))} = ${a2} y ${b} · ${P_(neg(m))} = ${b2}), pero el término independiente no: ${c} · ${P_(neg(m))} = ${mc}, que no es ${c2}. Las rectas son paralelas. Es <b>incompatible</b>.`,
  ],
  sm_q: (e1, e2) => `Resuelve el sistema: <b>${e1}</b>; <b>${e2}</b>.`,
  sm_s: (m1, m2, e1, e2, A, E, x, a, b, e, ax, rest, y) => `Por reducción, para que se vaya la y: ${m1 === "1" && m2 === "1" ? "las y ya tienen coeficientes opuestos" : `${m1 === "1" ? "dejamos la primera" : `multiplicamos la primera por ${m1}`} y ${m2 === "1" ? "dejamos la segunda" : `multiplicamos la segunda por ${m2}`}: ${e1} y ${e2}`}. Sumamos: ${A}x = ${E}, así que x = <b>${x}</b>. Sustituimos en la primera: ${a} · ${P_(x)}${TY(b)} = ${e}, es decir, ${ax}${TY(b)} = ${e}, así que ${b === "1" ? "" : `${BY(b)} = ${rest} e `}y = <b>${y}</b>. Solución: (${x}, ${y}).`,
  sm2_s: (k6, m, ms, r, rr, A, E, x, mx, y) => `Primero se ordenan. La primera, por 6 (el m.c.m. de 2 y 3): 3x + 2y = ${k6}. En la segunda se quita el paréntesis: ${m}x ${ms.startsWith("−") ? "− " + ms.slice(1) : "+ " + ms} − y = ${r}, es decir, ${m}x − y = ${rr}. Reducción: sumamos a la primera el doble de la segunda: ${A}x = ${E}, así que x = <b>${x}</b>. En la segunda: ${mx} − y = ${rr}, así que y = <b>${y}</b>.`,
  sp_q: [
    (t, j, f) => `La edad de una madre es ${["", "", "el doble", "el triple", "el cuádruple", "el quíntuple"][t]} de la de su hijo, y dentro de ${j} ${j === 1 ? "año" : "años"} será ${["", "", "el doble", "el triple", "el cuádruple"][f]}. ¿Qué edad tiene cada uno?`,
    (n, T) => `En una hucha hay ${n} billetes, unos de 5 € y otros de 10 €, que suman ${T} €. ¿Cuántos hay de cada clase?`,
    (p, q, A, u, v, B) => `${p} cafés y ${q} tostada${q > 1 ? "s" : ""} cuestan ${A} €; ${u} café${u > 1 ? "s" : ""} y ${v} tostadas cuestan ${B} €. ¿Cuánto cuesta un café y cuánto una tostada?`,
  ],
  sp_f: [["Madre", "Hijo"], ["De 5 €", "De 10 €"], ["Café (€)", "Tostada (€)"]],
  sp_s: [
    (x, y, t, j, f) => `Con x = edad de la madre e y = la del hijo: hoy, x = ${t}y. Dentro de ${j} años: x + ${j} = ${f}(y + ${j}). Sustituimos la primera en la segunda: ${t}y + ${j} = ${f}y + ${f * j}, así que ${t - f === 1 ? "" : `${t - f}y = ${f * j - j} e `}y = ${y}. Entonces x = ${t} · ${y} = ${x}. Madre <b>${x}</b> años, hijo <b>${y}</b> años. Comprobación: dentro de ${j} años, ${x + j} = ${f} · ${y + j} ✓.`,
    (a, b, n, T) => `Con x = billetes de 5 € e y = billetes de 10 €: x + y = ${n}; 5x + 10y = ${T}. Restamos a la segunda 5 veces la primera: 5y = ${T} − ${5 * n} = ${T - 5 * n}, así que y = ${b}; x = ${n} − ${b} = ${a}. Hay <b>${a}</b> billetes de 5 € y <b>${b}</b> de 10 €.`,
    (c, t, p, q, A, u, v, B, uA, pB, uq, pv, dv, dE, qt, pc) => `Con x = precio del café e y = precio de la tostada: ${p}x + ${q === 1 ? "" : q}y = ${A}; ${u === 1 ? "" : u}x + ${v}y = ${B}. Reducción: ${u === 1 ? "dejamos la primera" : `multiplicamos la primera por ${u}`} y multiplicamos la segunda por ${p}, para que la x tenga el mismo coeficiente: ${u * p}x + ${BY(String(uq))} = ${uA}; ${u * p}x + ${BY(String(pv))} = ${pB}. Restamos: ${BY(neg(dv))} = ${dE}, así que y = ${t}. En la primera: ${p}x = ${A} − ${qt} = ${pc}, así que x = ${c}. Café <b>${c} €</b>, tostada <b>${t} €</b>.`,
  ],

  pb_q: [
    p => `Calcula el vértice de la parábola <b>y = ${p}</b>.`,
    p => `¿En qué punto corta al eje Y la parábola <b>y = ${p}</b>? Escribe la ordenada.`,
    p => `¿En qué puntos corta al eje X la parábola <b>y = ${p}</b>? Escribe las abscisas.`,
    p => `¿Hacia dónde se abren las ramas de la parábola <b>y = ${p}</b>?`,
  ],
  pb_f: ["x del vértice", "y del vértice"],
  pb_o: ["Hacia arriba (tiene un mínimo)", "Hacia abajo (tiene un máximo)"],
  pb_s: [
    (nb, a2, h, k, s, v) => `${nb === 0 ? "Como b = 0, x<sub>v</sub> = −b/(2a) = <b>0</b>" : `x<sub>v</sub> = −b/(2a) = ${neg(nb)}/${a2 < 0 ? "(" + neg(a2) + ")" : a2} = <b>${h}</b>`}; sustituimos x = ${h} (con paréntesis si es negativo): y<sub>v</sub> = ${s} = ${v} = <b>${k}</b>.`,
    c => `Al hacer x = 0 queda y = c = <b>${c}</b>.`,
    (p, r, mb, D, sq, a2, dbl) => `Se resuelve ${p} = 0 con la fórmula: x = (${mb} ± √${D}) / ${a2.startsWith("−") ? "(" + a2 + ")" : a2} = (${mb} ± ${sq}) / ${a2.startsWith("−") ? "(" + a2 + ")" : a2}: x = <b>${r}</b>${dbl ? " (solución doble: la parábola toca el eje en el vértice)" : ""}.`,
    a => `El coeficiente de x² es ${neg(a)}, ${a > 0 ? "positivo: las ramas van <b>hacia arriba</b>" : "negativo: las ramas van <b>hacia abajo</b>"}.`,
  ],
  pm_q: [
    P => `Con ${P} m de valla se quiere cercar un terreno rectangular con la mayor área posible. ¿Cuál es esa área máxima, en m²?`,
    P => `Junto a una pared se quiere cercar un terreno rectangular con ${P} m de valla (la pared hace de cuarto lado). ¿Cuál es el área máxima, en m²?`,
    p => `¿En cuántos puntos corta al eje X la parábola <b>y = ${p}</b>?`,
    p => `¿Cuál es el vértice de la parábola <b>y = ${p}</b>?`,
  ],
  pm_o: ["En dos puntos", "En uno (el vértice)", "En ninguno"],
  pm_s: [
    (P, h, L, A) => `Si un lado mide x, el otro mide ${h} − x (la mitad de la valla). Área: A = x(${h} − x) = −x² + ${h}x, una parábola hacia abajo: su vértice es el máximo. x<sub>v</sub> = −b/(2a) = −${h}/(2 · (−1)) = ${L}. Los lados miden ${L} y ${h} − ${L} = ${L} (¡un cuadrado!) y el área es ${L} · ${L} = <b>${A}</b> m².`,
    (P, L, h, A) => `Si los dos lados que salen de la pared miden x, el otro mide ${P} − 2x. Área: A = x(${P} − 2x) = −2x² + ${P}x, hacia abajo. x<sub>v</sub> = −${P}/(2 · (−2)) = ${L}. Lados ${L} y ${P} − 2 · ${L} = ${h}; área ${L} · ${h} = <b>${A}</b> m².`,
    (b, a, c, D, n) => `Δ = b² − 4ac = ${b.startsWith("−") ? "(" + b + ")" : b}² − 4 · ${a} · ${c} = ${D}. ${["Como Δ &gt; 0, corta al eje X en <b>dos puntos</b>.", "Como Δ = 0, lo toca en <b>un punto</b>, el vértice.", "Como Δ &lt; 0, <b>no corta</b> al eje X."][n]}`,
    (f, h, q, a) => `En y = a(x − p)² + q el vértice es (p, q). Aquí el paréntesis es ${f}, que se anula en x = ${h}: el vértice es (<b>${h}</b>, <b>${q}</b>). ${a > 0 ? "Como a &gt; 0, es un mínimo." : "Como a &lt; 0, es un máximo."}`,
  ],
  rc_q: [
    (m, P) => `Escribe la ecuación de la recta de pendiente ${m} que pasa por el punto P${P}, en la forma y = mx + n.`,
    (e, P) => `Escribe la ecuación de la recta paralela a y = ${e} que pasa por el punto P${P}, en la forma y = mx + n.`,
    (r, q, T) => `Un fontanero cobra una cantidad fija por la visita y ${r} € por cada hora de trabajo. Por ${q} horas cobró ${T} €. ¿Cuánto cobra por la visita?`,
    (r, q, T) => `Un taller de bicis cobra una cantidad fija por revisar la bici y ${r} € por cada pieza cambiada. Por ${q} piezas cobró ${T} €. ¿Cuánto cobra por la revisión?`,
  ],
  rc_hint: "Escribe solo lo que va detrás de «y =», por ejemplo: −3x + 11",
  rc_par: m => `Paralela: misma pendiente, m = ${m}. `,
  rc_s: (y0, m, xx, mx, res, m2, x0, n, y02) => `Punto-pendiente: y − ${P_(y0)} = ${m === "1" ? "" : m === "−1" ? "−" : m}(${xx}), es decir, y = ${mx} ${y0.startsWith("−") ? "− " + y0.slice(1) : "+ " + y0}, o sea, y = <b>${res}</b>. Comprobación: para x = ${x0}, y = ${m2 === "1" ? "" : m2 === "−1" ? "−" : m2 + " · "}${P_(x0)}${n ? (n < 0 ? " − " : " + ") + Math.abs(n) : ""} = ${y02} ✓.`,
  rc_s2: (r, q, T, rq, F) => `Es una función afín: pendiente ${r} (€ por unidad) y pasa por el punto (${q}, ${T}). Punto-pendiente: y − ${T} = ${r}(x − ${q}), es decir, y = ${r}x − ${rq} + ${T} = ${r}x + ${F}. La parte fija (x = 0) es <b>${F} €</b>.`,
  fe_q: [
    "Mira la gráfica de la función. ¿Cuál es su dominio?",
    "Mira la gráfica de la función. ¿Cuál es su recorrido?",
    up => `Mira la gráfica de la función. ¿En qué intervalo ${up ? "decrece" : "crece"}?`,
    up => `Mira la gráfica de la función. ¿Cuál es su ${up ? "mínimo" : "máximo"} absoluto (el valor de y)?`,
  ],
  fe_s: [
    (a, b, ok) => `El dominio son los valores de x en los que hay gráfica: de ${a} a ${b}, con los extremos incluidos (los puntos están rellenos): <b>${ok}</b>. Ojo: el dominio se lee en el eje X, no en el Y.`,
    (a, b, ok) => `El recorrido son los valores de y que toma la función: del más bajo, ${a}, al más alto, ${b}: <b>${ok}</b>. Se lee en el eje Y.`,
    (up, a, b, ok) => `Leyendo de izquierda a derecha, la gráfica ${up ? "baja" : "sube"} entre x = ${a} y x = ${b}: ${up ? "decrece" : "crece"} en <b>${ok}</b>. Los intervalos se dan con valores de x, no de y.`,
    (up, v, at, rel, xr, dif) => `El ${up ? "mínimo" : "máximo"} absoluto es el valor de y ${up ? "más bajo" : "más alto"} de toda la gráfica: y = <b>${v}</b> (en x = ${at}).${dif ? ` Ojo: el ${up ? "mínimo" : "máximo"} relativo, en x = ${xr}, vale ${rel}, pero no es el ${up ? "más bajo" : "más alto"}: el absoluto está en un extremo de la gráfica.` : ""}`,
  ],
  ip_q: [
    (a, b, c) => `${a} grifos iguales llenan un depósito en ${b} horas. ¿Cuántas horas tardarían ${c} grifos?`,
    (a, b, c) => `Un tren a ${a} km/h tarda ${b} horas en hacer un trayecto. ¿Cuántas horas tardaría a ${c} km/h?`,
    (a, b, c) => `Una pizza familiar se reparte en trozos iguales: entre ${a} amigos tocan ${b} trozos a cada uno. ¿Cuántos trozos tocan si son ${c} amigos?`,
  ],
  ip_s: [
    (a, b, k, c, r) => `Grifos y horas son inversamente proporcionales (el doble de grifos, la mitad de tiempo): el producto es constante, k = ${a} · ${b} = ${k}. Con ${c} grifos: t = ${k} : ${c} = <b>${r}</b> horas.`,
    (a, b, k, c, r) => `Velocidad y tiempo son inversamente proporcionales: k = ${a} · ${b} = ${k} km (la distancia). A ${c} km/h: t = ${k} : ${c} = <b>${r}</b> horas.`,
    (a, b, k, c, r) => `Amigos y trozos por persona son inversamente proporcionales: k = ${a} · ${b} = ${k} trozos en total. Entre ${c}: ${k} : ${c} = <b>${r}</b> trozos cada uno.`,
  ],
  iq_q: k => `La función <b>y = ${k}/x</b>, ¿en qué cuadrantes tiene sus ramas y cómo es en cada rama?`,
  iq_o: ["1.º y 3.º, decreciente en cada rama", "2.º y 4.º, creciente en cada rama", "1.º y 3.º, creciente en cada rama", "2.º y 4.º, decreciente en cada rama"],
  iq_s: [
    k => `k = ${k} &gt; 0: x e y tienen el mismo signo, así que las ramas están en los cuadrantes <b>1.º y 3.º</b>, y en cada rama, al aumentar x, y disminuye: <b>decreciente</b>.`,
    k => `k = ${k} &lt; 0: x e y tienen signos contrarios, así que las ramas están en los cuadrantes <b>2.º y 4.º</b>, y en cada rama la función <b>crece</b>.`,
  ],
  iv_q: P => `La gráfica de una función de proporcionalidad inversa y = k/x pasa por el punto ${P}. ¿Cuánto vale k?`,
  iv_s: (x, y, k) => `k = x · y = ${x} · ${y.startsWith("−") ? "(" + y + ")" : y} = <b>${k}</b>.`,
  iv2_q: (k, x) => `Dada la función y = ${k}/x, calcula la imagen de x = ${x}.`,
  iv2_s: (k, x, v) => `y = ${fin(`${k}/${x.startsWith("−") ? "(" + x + ")" : x}`, v)}.`,

  // [pregunta, índice de la respuesta en lg_n, porqué]
  lg_n: () => ["La mediatriz del segmento AB", "La bisectriz del ángulo", "Una circunferencia", "Dos rectas paralelas", "La paralela media"],
  lg: (r, d) => [
    ["¿Qué figura forman los puntos del plano que están a la misma distancia de dos puntos A y B?", 0, "Cada punto de la <b>mediatriz</b> de AB (la perpendicular a AB por su punto medio) está a la misma distancia de A que de B, y no hay otros."],
    ["¿Qué figura forman los puntos del interior de un ángulo que están a la misma distancia de sus dos lados?", 1, "Los puntos que equidistan de los dos lados forman la <b>bisectriz</b>, la semirrecta que divide el ángulo en dos iguales."],
    [`¿Qué figura forman los puntos del plano que están a ${r} cm de un punto O?`, 2, `Todos los puntos a ${r} cm de O forman la <b>circunferencia</b> de centro O y radio ${r} cm (la línea, no el círculo).`],
    [`¿Qué figura forman los puntos del plano que están a ${d} cm de una recta?`, 3, `A ${d} cm de la recta hay puntos a los dos lados: forman <b>dos rectas paralelas</b> a ella, una a cada lado.`],
    ["¿Qué figura forman los puntos del plano que están a la misma distancia de dos rectas paralelas?", 4, "Los puntos que equidistan de dos paralelas forman otra paralela justo en medio: la <b>paralela media</b>."],
    ["¿Dónde están los centros de todas las circunferencias que pasan por dos puntos A y B?", 0, "El centro está a la misma distancia (el radio) de A y de B, así que está en la <b>mediatriz</b> de AB."],
  ],
  lga: (r, d) => [
    ["Un socorrista quiere colocarse a la misma distancia de dos boyas A y B. ¿En qué línea debe estar?", 0, "Debe estar a igual distancia de A y de B: en la <b>mediatriz</b> del segmento AB."],
    ["Un barco quiere navegar por una bahía con forma de ángulo, siempre a la misma distancia de las dos costas. ¿Qué línea sigue?", 1, "Equidistar de los dos lados de un ángulo es estar en su <b>bisectriz</b>."],
    [`Una cabra está atada a un poste con una cuerda de ${r} m. ¿Qué línea marca el borde de la zona a la que llega?`, 2, `Los puntos más lejanos a los que llega están a ${r} m del poste: una <b>circunferencia</b> de radio ${r} m.`],
    ["Por el centro de una carretera recta se pinta una línea a la misma distancia de los dos bordes. ¿Qué es esa línea?", 4, "Los bordes son dos rectas paralelas, y la línea que equidista de las dos es la <b>paralela media</b>."],
    [`Se quieren plantar árboles a ${d} m de una vía de tren recta. ¿Dónde pueden estar?`, 3, `A ${d} m de la vía, a un lado o al otro: en <b>dos rectas paralelas</b> a la vía.`],
  ],
  lgp_n: ["El circuncentro", "El incentro", "El baricentro", "El ortocentro"],
  lgp: [
    ["¿Qué punto de un triángulo está a la misma distancia de los tres vértices?", 0, "Está en las tres mediatrices, así que equidista de los tres vértices: es el <b>circuncentro</b>."],
    ["¿Qué punto de un triángulo está a la misma distancia de los tres lados?", 1, "Está en las tres bisectrices, así que equidista de los tres lados: es el <b>incentro</b>."],
    ["¿En qué punto se cortan las medianas de un triángulo (de cada vértice al punto medio del lado opuesto)?", 2, "Las medianas se cortan en el <b>baricentro</b>, el centro de gravedad del triángulo."],
    ["¿En qué punto se cortan las alturas de un triángulo?", 3, "Las alturas se cortan en el <b>ortocentro</b>."],
    ["¿Cuál es el centro de la circunferencia que pasa por los tres vértices de un triángulo?", 0, "Ese centro está a la misma distancia de los tres vértices: es el <b>circuncentro</b>, donde se cortan las mediatrices."],
    ["¿Cuál es el centro de la circunferencia inscrita en un triángulo (la que toca sus tres lados)?", 1, "Ese centro está a la misma distancia de los tres lados: es el <b>incentro</b>, donde se cortan las bisectrices."],
  ],
  in_q: [
    c => `Un ángulo central de una circunferencia mide ${c}°. ¿Cuánto mide un ángulo inscrito que abarca el mismo arco?`,
    i => `Un ángulo inscrito en una circunferencia mide ${i}°. ¿Cuánto mide el ángulo central que abarca el mismo arco?`,
    a => `AB es un diámetro de una circunferencia y C, otro punto de ella. Si el ángulo CAB mide ${a}°, ¿cuánto mide el ángulo CBA?`,
    a => `Un cuadrilátero está inscrito en una circunferencia. Uno de sus ángulos mide ${a}°. ¿Cuánto mide el ángulo opuesto?`,
  ],
  in_s: [
    (c, r) => `El ángulo inscrito mide la mitad del central: ${c}° : 2 = <b>${r}°</b>.`,
    (i, r) => `El central mide el doble del inscrito: 2 · ${i}° = <b>${r}°</b>.`,
    (a, r) => `El ángulo en C está inscrito en una semicircunferencia: mide 90°. Los tres ángulos del triángulo suman 180°: CBA = 180° − 90° − ${a}° = <b>${r}°</b>.`,
    (a, r) => `Los ángulos opuestos de un cuadrilátero inscrito suman 180°: 180° − ${a}° = <b>${r}°</b>.`,
  ],

  af_q: [
    L => `Un hexágono regular tiene ${L} cm de lado. Calcula su apotema y su área (con una cifra decimal).`,
    (b, h) => `Una ventana tiene forma de rectángulo de ${b} dm de ancho y ${h} dm de alto, con un semicírculo encima (su diámetro es el lado de arriba). ¿Cuál es su área, en dm²? (Una cifra decimal.)`,
  ],
  af_f: ["Apotema (cm)", "Área (cm²)"],
  af_s: [
    (L, m, L2, m2, a2, a, P, A) => `En el hexágono regular el radio mide lo mismo que el lado, ${L} cm. La apotema es un cateto del triángulo rectángulo de hipotenusa el radio (${L}) y otro cateto medio lado (${m}): a = √(${L}² − ${m}²) = √(${L2} − ${m2}) = √${a2} ≈ <b>${a}</b> cm. Perímetro: 6 · ${L} = ${P} cm. Área: P · a / 2 ≈ ${P} · ${a} / 2 ≈ <b>${A}</b> cm².`,
    (b, h, bh, r, s, A) => `Rectángulo: ${b} · ${h} = ${bh} dm². Semicírculo: su diámetro es el ancho, ${b}, así que el radio es ${r}: π · ${r}² / 2 ≈ ${s} dm². Total: ${bh} + ${s} ≈ <b>${A}</b> dm².`,
  ],
  tp_q: [
    (c, b, x) => `Una rampa recta de ${c} m sube ${b} m. ¿Cuánto avanza en horizontal? ¿A qué altura está un punto de la rampa que ha avanzado ${x} m en horizontal desde el pie?`,
    (c, b, x) => `Un cable tenso de ${c} m va desde la punta de un poste de ${b} m hasta el suelo. ¿A qué distancia del pie del poste está el anclaje? A ${x} m del anclaje, en dirección al poste, ¿a qué altura pasa el cable?`,
  ],
  tp_f: ["Horizontal (m)", "Altura (m)"],
  tp_s: (c, b, d, a, x, h) => `Pitágoras: la horizontal mide √(${c}² − ${b}²) = √${d} = <b>${a}</b> m. Tales: el triángulo pequeño (horizontal ${x}, altura h) y el grande (horizontal ${a}, altura ${b}) están en posición de Tales, así que h/${x} = ${b}/${a} y h = ${b} · ${x} / ${a} = <b>${h}</b> m.`,
  tr_q: (P, v) => `Aplica al punto P${P} la traslación de vector v = ${v}. ¿Cuáles son las coordenadas del punto trasladado P′?`,
  tr_s: (P, v, r, x, y, u, w) => `Se suman las coordenadas del punto y las del vector: P′ = (${x} + ${P_(u)}, ${y} + ${P_(w)}) = <b>${r}</b>.`,
  tr2_q: (P, Q) => `Una traslación lleva el punto P${P} al punto P′${Q}. ¿Cuál es el vector de la traslación?`,
  tr2_s: (v, x, y, x2, y2) => `v = P′ − P = (${x2} − ${P_(x)}, ${y2} − ${P_(y)}) = <b>${v}</b>.`,
  ve_q: (A, B) => `Halla las coordenadas y el módulo del vector que va de A${A} a B${B}.`,
  ve_f: "Módulo",
  ve_s: (bx, ax, by, ay, v, v1, v2, s, m) => `Coordenadas: llegada menos salida, AB = (${bx} − ${ax}, ${by} − ${ay}) = <b>${v}</b>. Módulo (Pitágoras): √(${v1}² + ${v2}²) = √${s} = <b>${m}</b>.`,
  ve2_q: (u, v) => `Se aplica la traslación de vector u = ${u} y después la de vector v = ${v}. ¿Cuál es el vector de la traslación que equivale a las dos?`,
  ve2_s: (u1, v1, u2, v2, r) => `Trasladar con u y después con v es trasladar con la suma u + v = (${u1} + ${v1}, ${u2} + ${v2}) = <b>${r}</b>.`,
  s2_q: [
    P => `Halla el simétrico del punto P${P} respecto de la recta y = x.`,
    (P, O) => `Halla el simétrico del punto P${P} respecto del punto O${O}.`,
  ],
  s2_s: [
    r => `La simetría respecto de la recta y = x intercambia las coordenadas: P′ = <b>${r}</b>.`,
    (O, a, x, b, y, r, a2, b2) => `O${O} es el punto medio de P y P′, así que P′ = (2 · ${a} − ${x}, 2 · ${b} − ${y}) = (${a2} − ${x}, ${b2} − ${y}) = <b>${r}</b>.`,
  ],
  or_fig: [["un triángulo equilátero", 3], ["un cuadrado", 4], ["un pentágono regular", 5], ["un hexágono regular", 6], ["un octógono regular", 8], ["un decágono regular", 10], ["un dodecágono regular", 12], ["un rectángulo (que no es cuadrado)", 2], ["un rombo (que no es cuadrado)", 2], ["una estrella regular de cinco puntas", 5], ["una estrella regular de seis puntas", 6], ["un eneágono regular (9 lados)", 9]],
  or_q: f => `¿Cuál es el orden de giro de ${f}? ¿Y el menor ángulo de giro que lo deja igual?`,
  or_f: ["Orden", "Ángulo (°)"],
  or_s: (f, n, a) => `Al dar una vuelta completa alrededor de su centro, ${f} coincide consigo mismo ${n} veces: su orden de giro es <b>${n}</b>, y el menor ángulo es 360° : ${n} = <b>${a}°</b>.`,
  oc_q: (a, b, same) => `Se aplica un giro de ${a}° en sentido antihorario y después otro de ${b}° en sentido ${same ? "antihorario" : "horario"}, con el mismo centro. ¿De cuántos grados es el giro que equivale a los dos?`,
  oc_s: (a, b, same, t) => same ? `Dos giros con el mismo centro equivalen a un giro de la suma de los ángulos: ${a + b > 360 ? `${a}° + ${b}° = ${a + b}°, que es una vuelta completa más ${a + b - 360}°: <b>${a + b - 360}°</b>` : `${a}° + ${b}° = <b>${a + b}°</b>`}.` : `El segundo giro va en sentido contrario: se restan, ${a}° − ${b}° = ${t}°. Equivale a un giro de <b>${Math.abs(t)}°</b> en sentido ${t > 0 ? "antihorario" : "horario"}.`,
  mo_n: ["", "", "", "triángulo equilátero", "cuadrado", "pentágono regular", "hexágono regular", "heptágono regular", "octógono regular", "eneágono regular", "decágono regular", "endecágono regular", "dodecágono regular"],
  mo_o: ["Sí", "No"],
  mo_q: [
    (n, f) => `¿Se puede cubrir el plano, sin huecos ni solapamientos, solo con ${f}s iguales (${n} lados)?`,
    f => `En el mosaico regular de ${f}s, ¿cuántos ${f}s se juntan en cada vértice?`,
    g => `En un vértice de un mosaico se juntan estos polígonos regulares: ${g}. ¿Cuántos lados tiene el polígono regular que completa el vértice?`,
  ],
  mo_s: [
    (n, a, ok, k) => `Ángulo interior: (${n} − 2) · 180° / ${n} = ${a}°. Para cubrir el plano, varios tienen que completar 360° en cada vértice: 360° : ${a}° = ${k}${ok ? `, un número entero: <b>sí</b> (se juntan ${k} en cada vértice).` : `, que no es un número entero: <b>no</b>.`}`,
    (n, a, k) => `Cada ángulo interior mide ${a}°, y en un vértice tienen que sumar 360°: 360° : ${a}° = <b>${k}</b>.`,
    (s, sum, f, name, m) => `Ángulos: ${s} = ${sum}°. Faltan 360° − ${sum}° = ${f}°, que es el ángulo interior del ${name}: <b>${m}</b> lados.`,
  ],
  gi_q: (P, g) => `Gira el punto P${P} un ángulo de ${neg(g)}° alrededor del origen (${g > 0 ? "en sentido antihorario" : "en sentido horario"}). ¿Dónde queda?`,
  gi_s: (g, r, x, y) => {
    const m = v => v.startsWith("−") ? `−(${v})` : `−${v}`;   // opuesto, escrito con la sustitución: −(−4)
    const sub = g === 90 ? `(${m(y)}, ${x})` : g === 180 ? `(${m(x)}, ${m(y)})` : `(${y}, ${m(x)})`;
    return `${g === 90 ? "Un giro de 90°: (x, y) → (−y, x)" : g === 180 ? "Un giro de 180°: (x, y) → (−x, −y)" : "Un giro de −90° (o 270°): (x, y) → (y, −x)"}. Con x = ${x} e y = ${y}: P′ = ${sub === r ? "" : sub + " = "}<b>${r}</b>.`;
  },
  si_q: (P, t) => `Halla el simétrico del punto P${P} respecto ${t}.`,
  si_t: ["del eje X", "del eje Y", "del origen de coordenadas"],
  si_s: [
    r => `Respecto del eje X, la y cambia de signo: P′ = <b>${r}</b>.`,
    r => `Respecto del eje Y, la x cambia de signo: P′ = <b>${r}</b>.`,
    r => `Respecto del origen, cambian de signo las dos coordenadas: P′ = <b>${r}</b>.`,
  ],

  ge_q: [
    (a, b) => `Dos ciudades están en las longitudes ${a} y ${b}. ¿Cuántas horas de diferencia horaria solar hay entre ellas?`,
    (a, b) => `Dos lugares están en el mismo meridiano, en las latitudes ${a} y ${b}. ¿A qué distancia están, aproximadamente, en km? (Usa 1° ≈ 111 km.)`,
    c => `Un lugar tiene las coordenadas ${c}. ¿En qué hemisferios está?`,
    (h0, L) => `Cuando en Greenwich son las ${h0}:00 (hora solar), ¿qué hora solar es en un lugar de longitud ${L}? (Escribe la hora, de 0 a 23.)`,
  ],
  ge_h: [
    (d, nm) => `Uno de los dos está ${nm ? "en el ecuador" : "en el meridiano de Greenwich"}: la diferencia es ${d}°. `,
    (a, b, nm) => `Están a distinto lado ${nm ? "del ecuador" : "de Greenwich"}: se suman, ${a}° + ${b}° = ${a + b}°. `,
    (a, b, nm) => `Están al mismo lado ${nm ? "del ecuador" : "de Greenwich"}: se restan, ${a}° − ${b}° = ${a - b}°. `,
  ],
  ge_o: ["Norte y oeste", "Norte y este", "Sur y oeste", "Sur y este"],
  ge_s: [
    (d, h) => `La Tierra gira 360° en 24 horas: 15° por hora. ${d}° : 15 = <b>${h} h</b>.`,
    (d, k) => `Diferencia de latitud: ${d}°. Distancia ≈ ${d} · 111 = <b>${k} km</b>.`,
    ok => `La latitud indica norte o sur del ecuador; la longitud, este u oeste del meridiano de Greenwich: <b>${ok.toLowerCase()}</b>.`,
    (L, n, e, h0, h) => `${L}° : 15° = ${n} husos ${e ? "al este" : "al oeste"} de Greenwich. Hacia el este el sol sale antes, así que la hora va adelantada; hacia el oeste, atrasada: ${h0} ${e ? "+" : "−"} ${n} = ${h0 + (e ? n : -n)}${h0 + (e ? n : -n) !== h ? ` (es decir, las ${h} del día ${h0 + (e ? n : -n) > 23 ? "siguiente" : "anterior"})` : ""}. Son las <b>${h}:00</b>.`,
  ],
  ph_sol: [
    [[[4, 3]], 3, "un tetraedro"], [[[6, 4]], 3, "un cubo"], [[[8, 3]], 4, "un octaedro"], [[[12, 5]], 3, "un dodecaedro"], [[[20, 3]], 5, "un icosaedro"],
    [[[12, 5], [20, 6]], 3, "el icosaedro truncado, la forma de un balón de fútbol"], [[[8, 3], [6, 4]], 4, "un cuboctaedro"], [[[2, 6], [6, 4]], 3, "un prisma hexagonal"],
    [[[2, 5], [5, 4]], 3, "un prisma pentagonal"], [[[8, 6], [6, 4]], 3, "un octaedro truncado"],
  ],
  ph_c: (c, n) => `${c} caras ${["", "", "", "triangulares", "cuadradas", "pentagonales", "hexagonales"][n]}`,
  ph_q: (f, k) => `Un poliedro tiene ${f}, y en cada vértice se juntan ${k} caras. ¿Cuántas aristas y cuántos vértices tiene?`,
  ph_f: ["Aristas", "Vértices"],
  ph_s: (l, L, A, k, V, C, name) => `Lados de todas las caras: ${l} = ${L}. Cada arista es lado de 2 caras: A = ${L} : 2 = <b>${A}</b>. Cada vértice es de ${k} caras: V = ${L} : ${k} = <b>${V}</b>. Comprobación con Euler: C + V = ${C} + ${V} = ${C + V} = A + 2 ✓. (Es ${name}.)`,
  ph_pr: n => `un prisma de base de ${n} lados`,
  ph_py: n => `una pirámide de base de ${n} lados`,
  pe_q: [
    (C, V, A) => `Un poliedro tiene ${V} vértices y ${A} aristas. ¿Cuántas caras tiene?`,
    (C, V, A) => `Un poliedro tiene ${C} caras y ${A} aristas. ¿Cuántos vértices tiene?`,
    (C, V, A) => `Un poliedro tiene ${C} caras y ${V} vértices. ¿Cuántas aristas tiene?`,
  ],
  pe_s: [
    (C, V, A, n) => `Euler: C + V = A + 2 → C + ${V} = ${A} + 2 → C = ${A + 2} − ${V} = <b>${C}</b> caras. (Puede ser ${n}.)`,
    (C, V, A, n) => `Euler: C + V = A + 2 → ${C} + V = ${A} + 2 → V = ${A + 2} − ${C} = <b>${V}</b> vértices. (Puede ser ${n}.)`,
    (C, V, A, n) => `Euler: C + V = A + 2 → ${C} + ${V} = A + 2 → A = ${C + V} − 2 = <b>${A}</b> aristas. (Puede ser ${n}.)`,
  ],
  pa_q3: (n, L) => `¿Cuál es el área total de un ${n} regular de ${L} cm de arista? (Una cifra decimal.)`,
  pa_s3: (L, m, h, a1, n, A) => `Cada cara es un triángulo equilátero de lado ${L}. Su altura, por Pitágoras: √(${L}² − ${m}²) ≈ ${h} cm. Área de una cara: ${L} · ${h} / 2 ≈ ${a1} cm². Hay ${n} caras: ${n} · ${a1} ≈ <b>${A}</b> cm².`,
  cp_q: [
    (L, h) => `Una pirámide de base cuadrada tiene ${L} cm de lado y ${h} cm de altura. Calcula la apotema de la pirámide (la altura de cada cara) y su área total.`,
    (L, h) => `Una pirámide de base cuadrada tiene ${L} cm de lado y ${h} cm de altura. Se corta por la mitad de su altura con un plano paralelo a la base. ¿Cuál es el volumen del tronco de pirámide que queda abajo, en cm³?`,
    (r, h) => `Un cono tiene ${r} cm de radio y ${h} cm de altura. Calcula su generatriz y su área lateral (con una cifra decimal).`,
    (r, g) => `¿Cuántos grados mide el sector circular del desarrollo de un cono de ${r} cm de radio y ${g} cm de generatriz?`,
  ],
  cp_f: ["Apotema (cm)", "Área total (cm²)", "Generatriz (cm)", "Área lateral (cm²)"],
  cp_s: [
    (h, k, s, a, P, AL, AB, AT) => `La apotema es la hipotenusa de un triángulo rectángulo de catetos la altura (${h}) y medio lado (${k}): a′ = √(${h}² + ${k}²) = √${s} = <b>${a}</b> cm. Área lateral: perímetro · a′ / 2 = ${P} · ${a} / 2 = ${AL} cm². Base: ${AB} cm². Total: ${AL} + ${AB} = <b>${AT}</b> cm².`,
    (L, h, Vg, l, hh, Vp, Vt) => `El tronco es la pirámide grande menos la pequeña. Por Tales, la pequeña tiene la mitad de altura y la mitad de lado. Grande: ${L}² · ${h} / 3 = ${Vg} cm³. Pequeña: ${l}² · ${hh} / 3 = ${Vp} cm³. Tronco: ${Vg} − ${Vp} = <b>${Vt}</b> cm³.`,
    (h, r, s, g, rg, AL) => `Generatriz (Pitágoras, con la altura y el radio): g = √(${h}² + ${r}²) = √${s} = <b>${g}</b> cm. Área lateral: π · r · g = π · ${r} · ${g} = ${rg}π ≈ <b>${AL}</b> cm².`,
    (r, g, r2, g2, f, a) => `El arco del sector mide lo que la circunferencia de la base: 2π · ${r} = ${r2}π. La circunferencia completa de radio ${g} mide ${g2}π. El sector es ${r2}π : ${g2}π = ${f} de la vuelta: 360° · ${f} = <b>${a}°</b>.`,
  ],

  ds_q: d => `Calcula la media, la varianza y la desviación típica de los datos: ${d}. (Varianza y desviación con dos decimales.)`,
  ds_f: ["Media", "Varianza", "Desviación típica"],
  ds_s: (m, sq, n, v, s, sum, tot, sqs, ssq, exact) => `Media = (${sum}) / ${n} = ${tot} / ${n} = ${m}. Desviaciones al cuadrado: ${sq}; suman ${ssq}. Varianza = ${ssq} / ${n} ${exact ? "=" : "≈"} <b>${v}</b>. Desviación típica = √(${ssq} / ${n}) ≈ <b>${s}</b>.`,
  cv_q: (d, s) => `Los datos ${d} tienen una desviación típica de ${s}. Calcula el coeficiente de variación, en porcentaje. (Una cifra decimal.)`,
  cv_s: (s, m, cv) => `CV = desviación típica / media = ${s} / ${m} ≈ <b>${cv} %</b>.`,
  dt2_q: t => `Calcula la media, la varianza y la desviación típica de los datos de esta tabla, con la fórmula abreviada (dos decimales):${t}`,
  dt2_s: (xf, sx, N, m, x2f, sx2, a, b, v, s) => `N = ${N}. Media: (${xf}) / ${N} = ${sx} / ${N} = <b>${m}</b>. Fórmula abreviada: varianza = Σx<sub>i</sub>²f<sub>i</sub> / N − x̄². Σx<sub>i</sub>²f<sub>i</sub> = ${x2f} = ${sx2}; ${sx2} / ${N} ≈ ${a} y x̄² ≈ ${b}: varianza ≈ <b>${v}</b>. Desviación típica ≈ <b>${s}</b>.`,
  ft_table: (vals, fs) => {
    const B = 'style="border:1px solid #a2a9b1;padding:4px 10px;text-align:center"';
    return `<table style="border-collapse:collapse;margin:8px 0"><tr><th ${B}>x<sub>i</sub></th>${vals.map(v => `<td ${B}>${v}</td>`).join("")}</tr><tr><th ${B}>f<sub>i</sub></th>${fs.map(f => `<td ${B}>${f}</td>`).join("")}</tr></table>`;
  },
  ag_table: (cls, fs) => {
    const B = 'style="border:1px solid #a2a9b1;padding:4px 10px;text-align:center"';
    return `<table style="border-collapse:collapse;margin:8px 0"><tr><th ${B}>Clase</th>${cls.map(c => `<td ${B}>${c}</td>`).join("")}</tr><tr><th ${B}>f<sub>i</sub></th>${fs.map(f => `<td ${B}>${f}</td>`).join("")}</tr></table>`;
  },
  ag_q: [
    t => `Calcula la media de estos datos agrupados (con dos decimales):${t}`,
    t => `¿Cuál es la clase modal de estos datos agrupados?${t}`,
    t => `¿Cuál es la clase mediana de estos datos agrupados?${t}`,
    t => `¿Cuál es la mediana de los datos de esta tabla?${t}`,
  ],
  ag_s: [
    (mk, xf, sx, N, m) => `Cada clase se representa por su marca de clase (el punto medio): ${mk}. Σx<sub>i</sub>f<sub>i</sub> = ${xf} = ${sx}, y N = ${N}. Media ≈ ${sx} / ${N} ≈ <b>${m}</b>.`,
    (c, f) => `La clase modal es la de mayor frecuencia: <b>${c}</b>, con ${f} datos.`,
    (N, h, acc, c) => `La mitad de ${N} es ${h}. Frecuencias acumuladas: ${acc}. La primera que llega a ${h} es la de <b>${c}</b>: esa es la clase mediana.`,
    (N, h, acc, ent, pos, me) => `N = ${N}; la mitad es ${h}. Frecuencias acumuladas: ${acc}. ${ent ? `Como ${h} es entera, la mediana es la media de los datos ${pos}.º y ${pos + 1}.º` : `El dato que está en el medio es el ${Math.ceil(pos)}.º`}: Me = <b>${me}</b>.`,
  ],
  mu_ctx: [
    ["Un instituto tiene", ["ESO", "Bachillerato", "FP"], "alumnos"],
    ["Un club deportivo tiene", ["Infantiles", "Juveniles", "Adultos"], "socios"],
    ["Una empresa tiene", ["Producción", "Oficinas", "Ventas"], "trabajadores"],
  ],
  mu_q: (g, N, names, n, u) => `${g} ${N[0]} ${u} en ${names[0]}, ${N[1]} en ${names[1]} y ${N[2]} en ${names[2]}. Se quiere una muestra estratificada proporcional de ${n}. ¿Cuántos hay que elegir de cada grupo?`,
  mu_s: (sum, T, names, N, ps, m, n) => `Total: ${sum} = ${T}. Cada grupo aporta a la muestra la misma proporción que tiene en la población: ${names.map((nm, i) => `${nm}: ${N[i]}/${T} = ${ps[i]} → ${ps[i]} · ${n} = <b>${m[i]}</b>`).join("; ")}. Comprobación: ${m.join(" + ")} = ${n}.`,
  sesgo_q: q => `${q} ¿Es una muestra sesgada?`,
  sesgo_o: ["Sí, está sesgada", "No, es una buena muestra"],
  sesgo: [
    ["Para saber cuánto gusta la comida del comedor escolar, se pregunta solo a los alumnos que repiten plato.", 1, "<b>Sí</b>: los que repiten son justo a los que más les gusta; la muestra no representa a todos."],
    ["Para estimar la altura media de los alumnos de un instituto, se mide solo a los de 1.º de ESO.", 1, "<b>Sí</b>: los de 1.º son los más jóvenes y bajos; no representan a todo el instituto."],
    ["Para saber si la gente usa el transporte público, se pregunta a las personas que salen de un aparcamiento de coches.", 1, "<b>Sí</b>: quien sale de un aparcamiento ha venido en coche; los usuarios del transporte público casi no aparecen."],
    ["Una influencer pregunta en sus historias «¿Te gusta mi nuevo perfume?» y el 92 % responde que sí.", 1, "<b>Sí</b>: solo contestan sus seguidores, y además los que se molestan en votar."],
    ["Para conocer las horas de sueño del alumnado de un instituto, se sortean 60 alumnos entre todos los de la lista del centro.", 0, "<b>No</b>: es un muestreo aleatorio simple; todos los alumnos tienen la misma probabilidad de salir."],
    ["Para saber qué deporte prefieren los vecinos de un barrio, se pregunta a la salida del campo de fútbol tras un partido.", 1, "<b>Sí</b>: a la salida de un partido casi todos son aficionados al fútbol."],
    ["Para conocer la opinión sobre un parque, se elige una de cada 20 viviendas de la lista del padrón del barrio, empezando por una al azar.", 0, "<b>No</b>: es un muestreo sistemático sobre una lista de todos los vecinos; no favorece a ningún grupo."],
    ["Para estimar cuántas horas de deberes hacen los alumnos de un instituto, se elige a la mitad de una clase de 3.º.", 1, "<b>Sí</b>: una sola clase de un solo curso no representa a todos los cursos del instituto."],
    ["En un instituto con un 60 % de alumnos de ESO y un 40 % de Bachillerato, se eligen al azar 30 alumnos de ESO y 20 de Bachillerato.", 0, "<b>No</b>: es un muestreo estratificado proporcional; cada grupo está representado según su tamaño."],
  ],
  cu_q: d => `Calcula los cuartiles y la mediana de los datos: ${d}.`,
  cq_pos: (name, frac, n, pos, ip, ent, v) => `${name}: posición ${n} · ${frac} = ${pos}, ${ent ? `entera: media de los datos ${ip}.º y ${ip + 1}.º, <b>${v}</b>` : `no entera: el dato ${ip}.º, <b>${v}</b>`}.`,
  at_q: d => `Con los datos ${d}, ¿hay algún valor atípico? Si lo hay, escríbelo; si no, escribe 0.`,
  at_s: (d, n, steps, q1, q3, ric, k, lo, hi, out) => `Ordenados (N = ${n}): ${d}. ${steps} RIC = Q<sub>3</sub> − Q<sub>1</sub> = ${q3} − ${q1} = ${ric}; 1,5 · RIC = ${k}. Límites: ${q1} − ${k} = ${lo} y ${q3} + ${k} = ${hi}. ${out !== undefined ? `El ${out} está fuera de esos límites: <b>es atípico</b>.` : "Ningún dato se sale de esos límites: <b>no hay atípicos</b> (respuesta: 0)."}`,
  cu_s: (d, n, steps) => `Ordenados (N = ${n}): ${d}. ${steps}`,
  ri_q2: d => `Calcula el rango intercuartílico (Q<sub>3</sub> − Q<sub>1</sub>) de los datos: ${d}.`,
  ri_s2: (d, n, steps, q1, q3, r) => `Ordenados (N = ${n}): ${d}. ${steps} RIC = Q<sub>3</sub> − Q<sub>1</sub> = ${q3} − ${q1} = <b>${r}</b>. Es el ancho de la caja en el diagrama de caja.`,

  pc_q: [
    s => `Se lanzan dos dados y se suman los puntos. ¿Cuál es la probabilidad de que la suma sea ${s}?`,
    (dado, n) => dado ? `Se lanza un dado ${n} veces. ¿Cuál es la probabilidad de sacar al menos un 6?` : `Se lanzan ${n} monedas. ¿Cuál es la probabilidad de obtener al menos una cara?`,
    j => `Se lanzan tres monedas. ¿Cuál es la probabilidad de obtener exactamente ${j} cara${j === 1 ? "" : "s"}?`,
    (ev, cara) => `Se lanzan un dado y una moneda. ¿Cuál es la probabilidad de sacar ${ev} y ${cara ? "cara" : "cruz"}?`,
  ],
  pc_ev: [["un 4", 1], ["un 6", 1], ["un número par", 3], ["un múltiplo de 3", 2], ["un número mayor que 4", 2], ["un número menor que 5", 4], ["un número impar", 3], ["un 1 o un 2", 2]],
  pc_s: [
    (s, f, v, cs) => `Hay 6 · 6 = 36 resultados igual de probables. ${f === 1 ? `Solo 1 caso suma ${s}, el ${cs[0]}` : `Suman ${s}: ${cs.slice(0, -1).join(", ")} y ${cs[cs.length - 1]}, ${f} casos`} de 36: P = ${fin(`${f}/36`, v)}.`,
    (dado, n, num, den, v) => dado ? `Es más fácil el contrario: no sacar ningún 6. En cada lanzamiento, no sacar un 6 tiene probabilidad 5/6, y los lanzamientos son independientes: (5/6)<sup>${n}</sup> = ${num}/${den}. Así, P(al menos un 6) = 1 − ${num}/${den} = ${fin(`${den - num}/${den}`, v)}.` : `Es más fácil el contrario: ninguna cara (todas cruz), (1/2)<sup>${n}</sup> = 1/${den}. Así, P(al menos una cara) = 1 − 1/${den} = ${fin(`${den - 1}/${den}`, v)}.`,
    (j, c, v) => `Hay 2 · 2 · 2 = 8 resultados, y ${c} ${c === 1 ? "tiene" : "tienen"} exactamente ${j} cara${j === 1 ? "" : "s"}: P = ${fin(`${c}/8`, v)}.`,
    (ev, cara, c, v) => `Son experimentos independientes: se multiplican. P(${ev}) = ${c}/6 y P(${cara ? "cara" : "cruz"}) = 1/2: P = ${c}/6 · 1/2 = ${fin(`${c}/12`, v)}.`,
  ],
  ar_q: (r, b, rep, k) => `Una bolsa tiene ${r} bolas rojas y ${b} azules. Se sacan dos bolas ${rep ? "con devolución (se devuelve la primera antes de sacar la segunda)" : "sin devolución"}. ¿Cuál es la probabilidad de ${["que las dos sean rojas", "que salga una de cada color", "que salga al menos una roja"][k]}?`,
  ar_s0r: (r, t, v, raw) => `Con devolución, la bolsa no cambia: P = ${r}/${t} · ${r}/${t} = ${fin(raw, v)}.`,
  ar_s0: (r, t, v, raw) => `Sin devolución, en la segunda extracción queda una roja menos: P = ${r}/${t} · ${r - 1}/${t - 1} = ${fin(raw, v)}.`,
  ar_s1r: (r, b, t, v, one, raw) => `Dos caminos del árbol: roja-azul y azul-roja. Se multiplica a lo largo de cada camino y se suman los caminos: P = ${r}/${t} · ${b}/${t} + ${b}/${t} · ${r}/${t} = ${one} + ${one} = ${fin(raw, v)}.`,
  ar_s1: (r, b, t, v, one, raw) => `Dos caminos del árbol: roja-azul y azul-roja. Se multiplica a lo largo de cada camino y se suman los caminos: P = ${r}/${t} · ${b}/${t - 1} + ${b}/${t} · ${r}/${t - 1} = ${one} + ${one} = ${fin(raw, v)}.`,
  ar_s2: (b, t, rep, aa, raw, v) => `Es más fácil el contrario: que las dos sean azules. P(AA) = ${b}/${t} · ${rep ? b : b - 1}/${rep ? t : t - 1} = ${aa}. Así, P(al menos una roja) = 1 − ${aa} = ${fin(raw, v)}.`,
  ad_ctx: [["Una jugadora de baloncesto", "sus tiros libres"], ["Un jugador de fútbol", "sus penaltis"], ["Una tenista", "sus primeros saques"]],
  ad_q: (who, what, p, k) => `${who} mete el ${p} % de ${what}. Si lanza dos, ¿cuál es la probabilidad de que ${["meta exactamente uno", "meta al menos uno", "no meta ninguno", "meta los dos"][k]}? (Con decimales.)`,
  ad_s: [
    (p, q, pp, pq, qq, a) => `Árbol con dos niveles: acierto (${p}) o fallo (${q}). Exactamente uno: acierto-fallo o fallo-acierto. P = ${p} · ${q} + ${q} · ${p} = ${pq} + ${pq} = <b>${a}</b>.`,
    (p, q, pp, pq, qq, a) => `Es más fácil el contrario: fallar los dos, ${q} · ${q} = ${qq}. P(al menos uno) = 1 − ${qq} = <b>${a}</b>.`,
    (p, q, pp, pq, qq, a) => `Fallar los dos: se multiplica a lo largo del camino fallo-fallo, ${q} · ${q} = <b>${a}</b>.`,
    (p, q, pp, pq, qq, a) => `Acertar los dos: se multiplica a lo largo del camino acierto-acierto, ${p} · ${p} = <b>${a}</b>.`,
  ],
  pt_ctx: [
    [(a, y, z) => `Llueve el ${a} % de los días. Si llueve, el autobús llega tarde el ${y} % de las veces; si no llueve, el ${z} %. ¿Cuál es la probabilidad de que el autobús llegue tarde un día cualquiera?`, ["llueve", "no llueve", "tarde"]],
    [(a, y, z) => `Un ${a} % de los alumnos de un instituto va en bici. De los que van en bici, el ${y} % llega antes de las 8:15; de los demás, el ${z} %. ¿Cuál es la probabilidad de que un alumno elegido al azar llegue antes de las 8:15?`, ["va en bici", "no va en bici", "antes de las 8:15"]],
    [(a, y, z) => `En una fábrica, la máquina A hace el ${a} % de las piezas y la B, el resto. El ${y} % de las piezas de A son defectuosas, y el ${z} % de las de B. ¿Cuál es la probabilidad de que una pieza al azar sea defectuosa?`, ["es de A", "es de B", "defectuosa"]],
  ],
  pt_q: (f, a, y, z) => f(a, y, z),
  pt_s: (ev, a, y, pa, a2, z, pb, t) => `Árbol: primero, si ${ev[0]} (${a}) o si ${ev[1]} (${a2}); después, ${ev[2]} o no. Dos caminos acaban en «${ev[2]}»: ${a} · ${y} = ${pa} y ${a2} · ${z} = ${pb}. Se suman: P = ${pa} + ${pb} = <b>${t}</b>.`,
  un_q: (N, a, b) => `Se elige al azar un número del 1 al ${N}. Sean A = «múltiplo de ${a}» y B = «múltiplo de ${b}». Calcula P(A ∪ B), la probabilidad de que sea múltiplo de ${a} o de ${b}.`,
  un_s: (N, a, b, nA, nB, both, l, raw, v) => `P(A) = ${nA}/${N} y P(B) = ${nB}/${N}. Los que son múltiplos de los dos (múltiplos de ${l}) se contarían dos veces: A ∩ B = {${both.join(", ")}}, P(A ∩ B) = ${both.length}/${N}. P(A ∪ B) = P(A) + P(B) − P(A ∩ B) = (${nA} + ${nB} − ${both.length})/${N} = ${fin(raw, v)}.`,
  un_bar: [["oros", 10, "una figura (sota, caballo o rey)", 12, 3], ["copas", 10, "un as", 4, 1], ["espadas", 10, "un 7", 4, 1], ["una figura", 12, "un as", 4, 0], ["bastos", 10, "un rey", 4, 1], ["un as", 4, "un 7", 4, 0], ["copas", 10, "una sota", 4, 1]],
  ub_q: (x, y) => `Se saca una carta de una baraja española de 40 cartas. ¿Cuál es la probabilidad de que sea ${x} o ${y}?`,
  ub_s: (x, nx, y, ny, nxy, raw, v) => `P(${x}) = ${nx}/40 y P(${y}) = ${ny}/40. ${nxy ? `Hay ${nxy} ${nxy === 1 ? "carta que es" : "cartas que son"} las dos cosas a la vez: no se pueden contar dos veces. P = ${nx}/40 + ${ny}/40 − ${nxy}/40 = ${fin(raw, v)}.` : `Son sucesos incompatibles (ninguna carta es las dos cosas): P = ${nx}/40 + ${ny}/40 = ${fin(raw, v)}.`}`,
  co_table: (a, b, c, d) => {
    const B = 'style="border:1px solid #a2a9b1;padding:4px 10px;text-align:center"';
    const row = (h, xs) => `<tr><th ${B}>${h}</th>${xs.map(x => `<td ${B}>${x}</td>`).join("")}</tr>`;
    return `<table style="border-collapse:collapse;margin:8px 0">${row("", ["Hace deporte", "No hace deporte", "Total"]).replace(/<td /g, "<th ").replace(/<\/td>/g, "</th>")}${row("Chicos", [a, b, a + b])}${row("Chicas", [c, d, c + d])}${row("Total", [a + c, b + d, a + b + c + d])}</table>`;
  },
  co_q: [
    t => `En un instituto se ha preguntado al alumnado si hace deporte:${t}Se elige al azar una persona que hace deporte. ¿Cuál es la probabilidad de que sea un chico?`,
    t => `En un instituto se ha preguntado al alumnado si hace deporte:${t}Se elige un chico al azar. ¿Cuál es la probabilidad de que haga deporte?`,
    t => `En un instituto se ha preguntado al alumnado si hace deporte:${t}Se elige al azar una persona que no hace deporte. ¿Cuál es la probabilidad de que sea una chica?`,
  ],
  co_s: [
    (a, n, v) => `Solo cuentan los que hacen deporte (${n}), y de ellos ${a} son chicos: P(chico | deporte) = ${fin(`${a}/${n}`, v)}.`,
    (a, n, v) => `Solo cuentan los chicos (${n}), y de ellos ${a} hacen deporte: P(deporte | chico) = ${fin(`${a}/${n}`, v)}.`,
    (a, n, v) => `Solo cuentan los que no hacen deporte (${n}), y de ellos ${a} son chicas: P(chica | no deporte) = ${fin(`${a}/${n}`, v)}.`,
  ],
});
})();
